static void emit_artist(FILE *out, const Artist *a) {
    fputs("<h1>", out);
    emit_escaped(out, a->name);          /* encodes & < > " */
    fputs("</h1><ul>", out);
    for (size_t i = 0; i < a->album_count; i++) {
        fputs("<li>", out);
        emit_escaped(out, a->albums[i].title);
        fputs("</li>", out);
    }
    fputs("</ul>", out);
}

